<?php require dirname(__DIR__).'/includes/app.php';require_admin();$id=(string)($_GET['id']??$_POST['id']??'');$list=read_json('projects.json',[]);$idx=null;foreach($list as $i=>$x)if(($x['id']??'')===$id)$idx=$i;if($idx===null){http_response_code(404);exit('Project not found');}$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';if($a==='save'){$list[$idx]['name']=trim((string)$_POST['name']);$list[$idx]['location']=trim((string)$_POST['location']);$list[$idx]['category']=trim((string)$_POST['category']);$list[$idx]['status']=trim((string)$_POST['status']);$list[$idx]['description']=trim((string)$_POST['description']);$list[$idx]['featured']=isset($_POST['featured']);$list[$idx]['images']=array_merge($list[$idx]['images']??[],save_uploaded_images($_FILES['images']??[]));$notice='Project saved.';}if($a==='delete_image'){$n=(int)$_POST['image'];$imgs=$list[$idx]['images']??[];if(isset($imgs[$n])){delete_project_image($imgs[$n]);array_splice($imgs,$n,1);$list[$idx]['images']=$imgs;}$notice='Image deleted.';}if($a==='move'){$n=(int)$_POST['image'];$dir=(string)$_POST['dir'];$imgs=$list[$idx]['images']??[];$to=$dir==='up'?$n-1:$n+1;if(isset($imgs[$n],$imgs[$to])){[$imgs[$n],$imgs[$to]]=[$imgs[$to],$imgs[$n]];$list[$idx]['images']=$imgs;}$notice='Image order updated.';}write_json('projects.json',$list);}$p=$list[$idx];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Project</title><link rel="stylesheet" href="<?=e(asset_url('/admin/admin.css'))?>"></head><body><main class="admin-main solo"><p><a href="<?=e(site_url('/admin/'))?>">← Back to dashboard</a></p><header><h1>Edit <?=e($p['name'])?></h1></header><?php if($notice):?><div class="success"><?=e($notice)?></div><?php endif;?><section class="panel"><form method="post" enctype="multipart/form-data" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($id)?>"><label>Job Name<input name="name" value="<?=e($p['name'])?>"></label><label>Location<input name="location" value="<?=e($p['location'])?>"></label><label>Category<input name="category" value="<?=e($p['category'])?>"></label><label>Status<input name="status" value="<?=e($p['status'])?>"></label><label class="full">Description<textarea name="description"><?=e($p['description'])?></textarea></label><label class="full">Add Photos<input type="file" name="images[]" multiple accept="image/*"></label><label class="check full"><input type="checkbox" name="featured" <?=!empty($p['featured'])?'checked':''?>> Featured</label><button>Save Project</button></form></section><section class="panel"><h2>Gallery Order</h2><div class="image-manager"><?php foreach($p['images']??[] as $i=>$img):?><article><img src="<?=e($img)?>" alt=""><div class="image-actions"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($id)?>"><input type="hidden" name="action" value="move"><input type="hidden" name="image" value="<?=$i?>"><button name="dir" value="up" <?=$i===0?'disabled':''?>>↑</button><button name="dir" value="down" <?=$i===count($p['images'])-1?'disabled':''?>>↓</button></form><form method="post" onsubmit="return confirm('Delete this image?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($id)?>"><input type="hidden" name="action" value="delete_image"><input type="hidden" name="image" value="<?=$i?>"><button class="danger">Delete</button></form></div></article><?php endforeach;?></div></section></main></body></html>